// Timelines have finite frames and never start themselves or loop automatically.
function initWalk(id,frames,onFrame){
  const root=$(`#${id}`);if(!root)return null;
  let index=0,timer=null,playing=false;
  const pause=()=>{clearTimeout(timer);timer=null;playing=false;root.classList.remove('is-playing');$('[data-action="play"]',root).textContent='Play sequence';};
  const render=()=>{const frame=frames[index];$$('.walk-node',root).forEach((n,i)=>{n.classList.toggle('active',i===frame.node);n.classList.toggle('done',i<frame.node);});$('.walk-track span',root).style.width=`${(index+1)/frames.length*100}%`;
    $('.walk-detail',root).innerHTML=`<h4>${frame.title}</h4><p>${frame.text}</p>`;
    $('.walk-counter',root).textContent=`${index+1} / ${frames.length} · ${playing?'Playing':index===frames.length-1?'Complete':'Paused'}`;
    $('[data-action="back"]',root).disabled=index===0;$('[data-action="step"]',root).disabled=index===frames.length-1;
    if(onFrame)onFrame(index,root);};
  const tick=()=>{if(!playing)return;if(index>=frames.length-1){pause();render();return;}index++;render();timer=setTimeout(tick,2200);};
  $('[data-action="play"]',root).addEventListener('click',()=>{if(playing){pause();render();return;}if(index===frames.length-1)index=0;playing=true;root.classList.add('is-playing');$('[data-action="play"]',root).textContent='Pause';render();timer=setTimeout(tick,2200);});
  $('[data-action="step"]',root).addEventListener('click',()=>{pause();index=Math.min(index+1,frames.length-1);render();});
  $('[data-action="back"]',root).addEventListener('click',()=>{pause();index=Math.max(index-1,0);render();});
  $('[data-action="restart"]',root).addEventListener('click',()=>{pause();index=0;render();});
  cleanup.push(pause);render();return {reset(){pause();index=0;render();},get index(){return index;},render};
}

function initChapter(id){
  if(id==='architecture')initWalk('architecture-walk',[
    {node:0,title:'1. The operator requests a paired replay.',text:'The browser sends a validated scenario and source/model selection. It does not write directly to MySQL or the event files.'},
    {node:1,title:'2. FastAPI checks the boundary.',text:'The API validates the request, resolves compatible observations/forecasts and hands the run request to the application service. Data readiness and run admission can reject invalid work.'},
    {node:2,title:'3. The run service coordinates background work.',text:'It records queued runs and an input manifest, then iterates the pure simulation. Each step proposes, validates and executes virtual dispatch.'},
    {node:3,title:'4. MySQL commits the market step.',text:'Order insertion, matching, both remaining-quantity updates and trade insertion share one relational transaction protected by a run-row lock.'},
    {node:4,title:'5. The journal records operational evidence.',text:'The service writes a state, agent decisions and a safety check, then advances SQL completed_steps. The dashboard later queries SQL and events to display the history.'}
  ]);
  if(id==='data')initWalk('ingestion-walk',[
    {node:0,title:'1. Retain the original bytes.',text:'An unchanged raw CSV is the source evidence. The original provider, source URL, unit, acquisition time and date bounds are recorded.'},
    {node:1,title:'2. Verify identity.',text:'The public source checks its pinned published checksum and records SHA-256 provenance. An upload gets a content hash and retained raw file.'},
    {node:2,title:'3. Validate meaning and quality.',text:'Parse units and timezone-aware dates. Reject invalid/nonfinite/negative values and ambiguous labels. Conflicting readings must not become invented training targets.'},
    {node:3,title:'4. Preserve the series identity.',text:'Source + region + series + metric + timestamp identifies one measurement. Exact repetitions are duplicates; an existing identity with another value/unit is a conflict.'},
    {node:4,title:'5. Commit observations and audit together.',text:'A relational transaction links sources/regions and observation rows and adds import audit evidence. Reimporting identical measurements does not increase row count.'}
  ]);
  if(id==='forecasting')initWalk('forecast-walk',[
    {node:0,title:'1. Create only causal features.',text:'Lag and rolling features are shifted into the past. Calendar values are known in advance. Forward-filled history can support features, but missing targets never become scored actuals.'},
    {node:1,title:'2. Fit candidates on the training segment.',text:'The fixed candidates are seasonal persistence, absolute XGBoost and residual XGBoost. Their training cannot use validation or final-test labels for fitting.'},
    {node:2,title:'3. Choose on validation MAE.',text:'The lowest validation MAE wins, with ties going to persistence. Calibrate interval radii on validation residuals. This example follows the implementation, including reuse of validation for both tasks.'},
    {node:3,title:'4. Freeze the choice, then score the final test.',text:'Final-test errors and empirical coverage are reported for every candidate. They do not change the champion. The saved selected model loses to persistence on this period; that outcome is part of the result.'}
  ]);
  if(id==='agents'){
    initWalk('agents-walk',[
      {node:0,title:'1. Build the step context.',text:'Read the actual input reference and current virtual battery state; calculate the modelled demand, renewable availability, limits and tariff.'},
      {node:1,title:'2. Specialists propose.',text:'Risk/forecast, resource, demand, market and critical-facility agents each return structured numerical actions and explanations. An agent error is recorded.'},
      {node:2,title:'3. The coordinator assembles one plan.',text:'It resolves battery movement, allowed flexibility, grid flow and market allocation. Being coordinated is not yet being safe.'},
      {node:3,title:'4. Independent safety checks the plan.',text:'Validate finite values, bounds, exclusive modes, critical priority, market budgets and energy conservation. Rejections keep explicit reasons.'},
      {node:4,title:'5. Execute only an approved plan or fallback.',text:'A fallback disables battery motion, flexibility and market orders, uses renewables/bounded imports and prioritizes critical load. It must pass a fresh validation; otherwise the step fails.'}
    ]);
    const update=()=>{const value=Number($('#discharge-input').value);$('#discharge-value').textContent=`${value} kW`;const bad=value>60;$('#safety-result').classList.toggle('bad',bad);$('#safety-result').innerHTML=bad?`<strong>Original proposal rejected.</strong> ${value} kW exceeds the 60 kW converter limit. Illustrative safe fallback: discharge 0 kW; use available renewables and bounded imports, prioritize critical load and record any unmet demand. The full fallback must still pass every check.`:`<strong>Battery bound passes.</strong> ${value} kW ≤ min(60, (144 − 36) × 0.95 / 0.5) = 60 kW. Next battery energy would be ${(144-value/0.95*0.5).toFixed(3)} kWh. The full dispatch still needs the remaining safety checks.`;};$('#discharge-input').addEventListener('input',update);update();
  }
  if(id==='physics'){const update=()=>{const value=Number($('#charge-input').value),next=144+value*.95*.5;$('#charge-value').textContent=`${value} kW`;$('#battery-next').textContent=`${next.toFixed(2)} kWh · ${(next/240*100).toFixed(1)}% SoC`;$('#battery-working').textContent=`144 + ${value} × 0.95 × 0.5 = ${next.toFixed(2)} kWh`;$('.battery-fill').style.height=`${next/240*100}%`;$('#battery-visual').setAttribute('aria-label',`Next battery energy ${next.toFixed(2)} kWh, ${(next/240*100).toFixed(1)} percent state of charge`);};$('#charge-input').addEventListener('input',update);update();}
  if(id==='transactions')initTransaction();
  if(id==='schema'){
    const inspect=name=>{const e=entities[name];$('#entity-info').innerHTML=`<span class="card-number">${esc(e.group)}</span><h3>${esc(name)}</h3><p>${e.why}</p><ul class="entity-columns">${e.fields.map(([key,value])=>`<li>${key?`<span class="key-label">${esc(key)}</span>`:''}<code>${esc(value)}</code></li>`).join('')}</ul><h4>Relationships</h4>${e.relations.length?e.relations.map(([from,cardinality,to])=>`<div class="entity-relation">${esc(from)} <span>${esc(cardinality)}</span> ${esc(to)}</div>`).join(''):'<p>No declared foreign keys. Its independent purpose is audit or schema governance.</p>'}<div class="result-box">${e.rule}</div>`;$$('[data-entity]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.entity===name)));};
    $$('[data-entity]').forEach(b=>b.addEventListener('click',()=>inspect(b.dataset.entity)));$$('[data-entity-svg]').forEach(g=>{g.addEventListener('click',()=>inspect(g.dataset.entitySvg));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(g.dataset.entitySvg);}});});inspect('energy_observations');
  }
  if(id==='sql')initIndex();
  if(id==='events'){
    const update=()=>{const field=$('#event-step'),raw=Number(field.value);if(!Number.isInteger(raw)||raw<0||raw>335){$('#event-key').innerHTML='<span>CHOOSE A VALID STEP</span>Use an integer from 0 through 335 for this illustration.';return;}const step=String(raw).padStart(8,'0'),type=$('#event-type').value;$('#event-key').innerHTML=`<span>PARTITION KEY · SAME FOR ALL EVENTS IN THIS RUN</span>RUN#123e4567-e89b-42d3-a456-426614174000<br><br><span>SORT KEY · STEP + CATEGORY + STABLE EVENT HASH</span>STEP#${step}#${type}#&lt;event-hash&gt;<br><br><span>STEP QUERY PREFIX · MATCHES ALL CATEGORIES FOR THIS STEP</span>STEP#${step}#`;};$('#event-step').addEventListener('input',update);$('#event-type').addEventListener('change',update);update();
    initWalk('failure-walk',[
      {node:0,title:'1. Dispatch passes safety.',text:'The numerical step is ready. Settlement starts a SQL transaction with orders and matching. No operational event has been written for this step yet.'},
      {node:1,title:'2. Market settlement commits.',text:'The orders and trades now persist in MySQL. The event journal is not a participant in that SQL transaction.'},
      {node:2,title:'3. Inject a journal failure.',text:'Suppose the state writes but a later agent decision or safety event cannot be saved. The SQL trade remains committed; the operational history is incomplete.'},
      {node:3,title:'4. The completed-step counter does not advance.',text:'The service only increments completed_steps after all step events are written. Existing market rows and events expose the partial work.'},
      {node:4,title:'5. Mark the run failed and preserve evidence.',text:'If SQL remains available, the error is recorded and no final metrics are published. A SQL outage can prevent that status write. A process restart marks previously active runs interrupted; start a new run after investigation. No distributed rollback or automatic checkpoint resume is claimed.'}
    ]);
  }
}

function initTransaction(){
  let committed=false;
  const fault=()=>$('#transaction-fault').checked;
  const frames=[
    {node:0,title:'1. BEGIN; lock the run row.',text:'SELECT … FOR UPDATE serializes this run’s order book in MySQL. The illustrative committed book is empty. Other app settlements for this run wait for the lock.'},
    {node:1,title:'2. Insert two pending orders.',text:'Buy 8 kWh at a limit of 8; sell 10 kWh at 4. The rows exist inside this transaction, and have not committed.'},
    {node:2,title:'3. Match and update both quantities.',text:'Allocate min(8, 10) = 8 kWh. Buy remaining becomes 0, sell remaining becomes 2. Both changes are still pending in the same transaction.'},
    {node:3,title:'4. Insert the pending trade.',text:'The trade links both order IDs, the same run/step, quantity 8 kWh and midpoint price (8 + 4) / 2 = 6 per kWh. Constraints/guards must pass.'},
    {node:4,title:'',text:''}
  ];
  const renderLedger=(index,root)=>{
    const final=index===4,failed=final&&fault(),pending=index>0&&!final;committed=final&&!failed;
    if(final){frames[4].title=failed?'5. Failure before COMMIT → ROLLBACK.':'5. COMMIT; release the lock.';frames[4].text=failed?'The injected exception rolls back the inserted orders, both quantity changes and the trade. No new committed rows remain. A retry can start this step again.':'All order and trade changes become committed together. An identical whole-step retry reuses the result; a different order payload conflicts.';$('.walk-detail',root).innerHTML=`<h4>${frames[4].title}</h4><p>${frames[4].text}</p>`;}
    const visible=index>0&&!failed;const adjusted=index>=2;
    $('.walk-extra',root).innerHTML=`<div class="ledger"><div class="ledger-cell"><div class="ledger-label">Buyer order</div><strong>${visible?'8 kWh @ limit 8':'No new row'}</strong><span>${visible?`Remaining: ${adjusted?'0':'8'} kWh`:'Committed book empty'}</span></div><div class="ledger-cell"><div class="ledger-label">Seller order</div><strong>${visible?'10 kWh @ limit 4':'No new row'}</strong><span>${visible?`Remaining: ${adjusted?'2':'10'} kWh`:'Committed book empty'}</span></div><div class="ledger-cell"><div class="ledger-label">Trade ledger</div><strong>${index>=3&&!failed?'8 kWh @ price 6':'No new trade'}</strong><span>${index>=3&&!failed?'Value: 48 currency units':'No committed allocation yet'}</span></div></div><div class="transaction-status">${failed?'ROLLED BACK · 0 committed orders · 0 committed trades':committed?'COMMITTED · 2 orders · 1 trade':pending?'PENDING INSIDE TRANSACTION · committed book still empty':'TRANSACTION OPEN · lock held · committed book empty'}</div>`;
    $('#retry-result').classList.remove('bad');$('#retry-result').textContent=committed?'Committed. Try the identical retry, then a changed quantity.':'Finish the animation with failure injection off to demonstrate retries of a committed step.';
  };
  const timeline=initWalk('transaction-walk',frames,renderLedger);
  $('#transaction-fault').addEventListener('change',()=>timeline.reset());
  $('#retry-identical').addEventListener('click',()=>{const r=$('#retry-result');r.classList.remove('bad');r.textContent=committed?'Identical retry: existing run/step orders match. No writes. Still 2 orders, 1 trade, buy remaining 0 and sell remaining 2.':'There is no committed example yet. Finish the sequence with failure injection off first.';});
  $('#retry-changed').addEventListener('click',()=>{const r=$('#retry-result');r.classList.toggle('bad',committed);r.textContent=committed?'Idempotency conflict: this run/step already committed different orders (buyer quantity 8, not 9). The committed 2 orders and 1 trade stay unchanged.':'There is no committed example yet. Finish the sequence with failure injection off first.';});
}

function initIndex(){
  let mode='scan',position=0,timer=null,playing=false;
  const matches=[32,33,34,35,36,37];
  const sequence=()=>mode==='scan'?Array.from({length:48},(_,i)=>i):matches;
  const pause=()=>{clearTimeout(timer);timer=null;playing=false;$('#index-play').textContent='Play lookup';};
  const render=()=>{const inspected=sequence().slice(0,position);$('#index-grid').innerHTML=Array.from({length:48},(_,i)=>`<span class="index-row${inspected.includes(i)?matches.includes(i)?' match':' checked':''}">${String(i+1).padStart(2,'0')}</span>`).join('');$('#index-status').textContent=`${position} illustrated entries visited · ${inspected.filter(i=>matches.includes(i)).length} / 6 matches${position===sequence().length?' · Complete':''}`;$('#index-step').disabled=position===sequence().length;};
  const reset=()=>{pause();position=0;render();};
  const tick=()=>{if(!playing)return;if(position>=sequence().length){pause();render();return;}position++;render();timer=setTimeout(tick,mode==='scan'?100:400);};
  $('#index-mode-scan').addEventListener('click',()=>{mode='scan';$('#index-mode-scan').setAttribute('aria-pressed','true');$('#index-mode-index').setAttribute('aria-pressed','false');reset();});
  $('#index-mode-index').addEventListener('click',()=>{mode='index';$('#index-mode-scan').setAttribute('aria-pressed','false');$('#index-mode-index').setAttribute('aria-pressed','true');reset();});
  $('#index-play').addEventListener('click',()=>{if(playing){pause();render();return;}if(position===sequence().length)position=0;playing=true;$('#index-play').textContent='Pause';render();timer=setTimeout(tick,150);});
  $('#index-step').addEventListener('click',()=>{pause();position=Math.min(sequence().length,position+1);render();});$('#index-reset').addEventListener('click',reset);cleanup.push(pause);render();
}

if(location.protocol==='file:')$('#notes-link').href='../../docs/LEARNING_GUIDE.md';
const initial=chapters.findIndex(c=>c.id===location.hash.slice(1));current=initial<0?0:initial;renderChapter();
